    "The first use loads about 6.6 MB from this site. The photo is processed on your device. A computer is recommended for large images.": "การใช้งานครั้งแรกจะมีการโหลดข้อมูลประมาณ 6.6 MB จากเว็บไซต์นี้ รูปภาพจะถูกประมวลผลบนอุปกรณ์ของคุณ แนะนำให้ใช้คอมพิวเตอร์สำหรับรูปภาพขนาดใหญ่",
