    "Model loading": "กำลังโหลดโมเดล",
    "Processing the photo locally…": "กำลังประมวลผลรูปภาพบนอุปกรณ์...",
    "Choose an image first.": "โปรดเลือกรูปภาพก่อน",
    "Ready to remove the background.": "พร้อมลบพื้นหลังแล้ว",
    "Portrait image must be 20 megapixels or smaller. Resize it before processing.": "รูปภาพบุคคลต้องมีความละเอียดไม่เกิน 20 ล้านพิกเซล โปรดปรับขนาดรูปภาพก่อนเริ่มประมวลผล",
    "Background removal complete. Review the edges before using the image.": "ลบพื้นหลังเสร็จสิ้น โปรดตรวจสอบขอบภาพก่อนนำไปใช้งาน",
