    "Choose PDF file(s)": "เลือกไฟล์ PDF",
    "Choose an image": "เลือกรูปภาพ",
    "PDFs are processed on this device and are never uploaded. There is no fixed file-size cap; available memory and browser support are the practical limits.": "ไฟล์ PDF จะถูกประมวลผลบนอุปกรณ์นี้และไม่มีการอัปโหลดขึ้นเซิร์ฟเวอร์ ไม่มีการจำกัดขนาดไฟล์ตายตัว ข้อจำกัดที่แท้จริงขึ้นอยู่กับหน่วยความจำที่มีอยู่และการรองรับของเบราว์เซอร์",
    "PDFs are processed on this device and are never uploaded. There is no fixed file-size cap; available memory and browser support are the practical limits. Choose up to 10 PDFs to merge.": "ไฟล์ PDF จะถูกประมวลผลบนอุปกรณ์นี้และไม่มีการอัปโหลดขึ้นเซิร์ฟเวอร์ ไม่มีการจำกัดขนาดไฟล์ตายตัว ข้อจำกัดที่แท้จริงขึ้นอยู่กับหน่วยความจำที่มีอยู่และการรองรับของเบราว์เซอร์ เลือกไฟล์ PDF ได้สูงสุด 10 ไฟล์เพื่อรวมเข้าด้วยกัน",
    "JPG, PNG or WebP. No fixed file-size cap. Very large images depend on device memory; output is limited to 40 megapixels.": "JPG, PNG หรือ WebP ไม่มีการจำกัดขนาดไฟล์ตายตัว สำหรับรูปภาพขนาดใหญ่มากจะขึ้นอยู่กับหน่วยความจำของอุปกรณ์ โดยผลลัพธ์จะจำกัดความละเอียดสูงสุดที่ 40 ล้านพิกเซล",
