    "For long or high-resolution media, a desktop or laptop is recommended. Keep this tab open; speed, memory and battery depend on your device.": "สำหรับสื่อที่มีความยาวหรือความละเอียดสูง แนะนำให้ใช้คอมพิวเตอร์ตั้งโต๊ะหรือแล็ปท็อป โปรดเปิดแท็บนี้ค้างไว้ ความเร็ว หน่วยความจำ และแบตเตอรี่ขึ้นอยู่กับอุปกรณ์ของคุณ",
    "Re-encoding can reduce sound quality or make a larger file. Your original stays unchanged.": "การเข้ารหัสใหม่ (re-encoding) อาจทำให้คุณภาพเสียงลดลงหรือไฟล์มีขนาดใหญ่ขึ้น ไฟล์ต้นฉบับของคุณจะไม่มีการเปลี่ยนแปลง",
    "First use downloads about 58 MB of model and local engine. Your recording is not uploaded; the browser may download them again if its cache is cleared.": "การใช้งานครั้งแรกจะดาวน์โหลดโมเดลและเอนจินภายในเครื่องขนาดประมาณ 58 MB ไฟล์บันทึกเสียงของคุณจะไม่ถูกอัปโหลดขึ้นเซิร์ฟเวอร์ เบราว์เซอร์อาจดาวน์โหลดข้อมูลเหล่านี้ใหม่อีกครั้งหากมีการล้างแคช",
